-- Atlas local database (SQLite), file: <app_data_dir>/atlas.db
--
-- Atlas is a sync companion: launchers (Prism, Modrinth App, CurseForge, ...) own the instances
-- and download the game. Atlas tracks their instance folders, shares them, and applies updates.
--
-- Run on every connection (not in a migration):
--   PRAGMA foreign_keys = ON;
--   PRAGMA journal_mode = WAL;
--
-- Conventions (see docs/data-plan.md):
--   ids         TEXT, UUIDv7, generated by the app (works offline, sorts by creation time)
--   timestamps  TEXT, ISO-8601 UTC with millis, e.g. '2026-10-19T16:39:00.000Z'
--   booleans    INTEGER 0/1
--   enums       TEXT + CHECK constraint, values are snake_case
--   json        TEXT holding JSON (arrays/objects that are never queried by field)
--   paths       absolute only where the folder belongs to someone else (launcher roots, game dirs);
--               everything inside a game dir is relative, with forward slashes
--
-- Never edit this file after it has shipped. Add 0002_*.sql instead.

-- Launcher installs found on this PC (or added by hand, e.g. a portable Prism).
CREATE TABLE launcher (
  id               TEXT PRIMARY KEY,
  kind             TEXT NOT NULL CHECK (kind IN ('prism', 'multimc', 'modrinth', 'curseforge', 'official')),
  root_path        TEXT NOT NULL UNIQUE,     -- e.g. C:\Users\x\AppData\Roaming\PrismLauncher
  added_by_user    INTEGER NOT NULL DEFAULT 0, -- 0 = found by auto-detection
  last_scanned_at  TEXT,
  created_at       TEXT NOT NULL
);

-- One row per tracked instance. The folder belongs to the launcher; Atlas never moves or renames it.
CREATE TABLE instance (
  id                      TEXT PRIMARY KEY,
  launcher_id             TEXT REFERENCES launcher (id) ON DELETE SET NULL, -- NULL = folder added by hand
  launcher_kind           TEXT NOT NULL CHECK (launcher_kind IN ('prism', 'multimc', 'modrinth', 'curseforge', 'official', 'folder')),
  launcher_instance_id    TEXT,               -- the launcher's own key: Prism folder name, Modrinth profile path, CF folder name, official profile id
  game_dir                TEXT NOT NULL UNIQUE, -- absolute path of the folder holding mods/, config/, saves/

  -- Mirrored from the launcher's metadata on every scan (the launcher is the source of truth).
  name                    TEXT NOT NULL,
  icon                    TEXT,               -- launcher icon key or 'file:<absolute path>'
  minecraft_version       TEXT,               -- NULL if the launcher metadata couldn't be read
  loader                  TEXT CHECK (loader IN ('vanilla', 'fabric', 'quilt', 'forge', 'neoforge')),
  loader_version          TEXT,
  last_played_at          TEXT,               -- from the launcher, when it records it
  total_playtime_seconds  INTEGER,            -- from the launcher (Prism does; others may not) — NULL = unknown

  status                  TEXT NOT NULL DEFAULT 'ready' CHECK (status IN ('ready', 'missing')),
                                              -- missing = folder gone (deleted or moved in the launcher)

  -- Atlas-only preferences
  is_favorite             INTEGER NOT NULL DEFAULT 0,
  hide_activity           INTEGER NOT NULL DEFAULT 0,  -- 1 = friends see "Playing Minecraft", not the name

  -- Link to a cloud shared instance. All NULL = only on this PC.
  shared_instance_id      TEXT,
  shared_role             TEXT CHECK (shared_role IN ('owner', 'editor', 'viewer')),
  synced_revision         INTEGER,            -- cloud revision this folder was last made equal to
  synced_manifest_hash    TEXT,               -- hash of the managed content at that revision (detects local edits)
  synced_manifest         TEXT,               -- the manifest JSON at synced_revision: finds deleted files, diffs updates, reverts offline
  sync_report_due         INTEGER NOT NULL DEFAULT 0, -- 1 = the server hasn't been told synced_revision yet (offline at the time)
  sync_include            TEXT NOT NULL DEFAULT '["config/**"]', -- JSON globs of extra files shared as overrides

  tracked_at              TEXT NOT NULL,
  last_scanned_at         TEXT,

  CHECK ((shared_instance_id IS NULL) = (shared_role IS NULL)),
  UNIQUE (launcher_kind, launcher_instance_id)
);

CREATE UNIQUE INDEX instance_shared_instance_id_idx
  ON instance (shared_instance_id) WHERE shared_instance_id IS NOT NULL;

-- Index of the files found by the last scan of an instance folder.
-- Rescans skip hashing when (path, size_bytes, mtime_ms) are unchanged.
-- Also lists optional items from the shared version that the user chose not to download
-- (installed = 0): they have no file on disk, so the hashes/size come from the manifest.
CREATE TABLE instance_content (
  id             TEXT PRIMARY KEY,
  instance_id    TEXT NOT NULL REFERENCES instance (id) ON DELETE CASCADE,

  kind           TEXT NOT NULL CHECK (kind IN ('mod', 'resourcepack', 'shaderpack', 'datapack')),
  path           TEXT NOT NULL,           -- relative to game_dir, without '.disabled': 'mods/sodium-0.6.0.jar'
  enabled        INTEGER NOT NULL DEFAULT 1, -- 0 = file on disk ends in '.disabled' (convention all launchers use)
  size_bytes     INTEGER NOT NULL,
  mtime_ms       INTEGER,                 -- NULL when installed = 0 (no file on disk)
  sha1           TEXT NOT NULL,           -- Modrinth lookup + download cache key
  sha256         TEXT NOT NULL,           -- Atlas blob key + manifest hashing
  murmur2        INTEGER,                 -- CurseForge fingerprint

  -- Where the file comes from, resolved by hash (see backend-plan §6.3)
  -- modrinth/curseforge: found on that site. upload: hosted on Atlas R2. local: unknown, only on this PC.
  source         TEXT NOT NULL DEFAULT 'local' CHECK (source IN ('modrinth', 'curseforge', 'upload', 'local')),
  project_id     TEXT,
  version_id     TEXT,
  name           TEXT NOT NULL,           -- provider title when resolved, else file name
  version_label  TEXT,
  author         TEXT,
  icon_url       TEXT,
  download_url   TEXT,                    -- NULL for CurseForge files with third-party downloads disabled
  page_url       TEXT,
  side           TEXT NOT NULL DEFAULT 'both' CHECK (side IN ('client', 'server', 'both')),
  resolved_at    TEXT,                    -- last time the hash was looked up (retry unknowns weekly)

  is_managed     INTEGER NOT NULL DEFAULT 0, -- 1 = in the shared version (required or optional); sync may replace/remove it

  -- How this file is shared (see data-plan §7):
  --   owners/editors: their setting; viewers: as published (their own extras are 'private')
  share_mode            TEXT NOT NULL DEFAULT 'required' CHECK (share_mode IN ('required', 'optional', 'private')),
  -- Setting at the last publish; NULL = never published. Differs from share_mode = a change to publish.
  published_share_mode  TEXT CHECK (published_share_mode IN ('required', 'optional', 'private')),
  -- 0 = optional item from the shared version the user didn't download (no file on disk)
  installed             INTEGER NOT NULL DEFAULT 1,

  UNIQUE (instance_id, path)
);

CREATE INDEX instance_content_instance_id_idx ON instance_content (instance_id);
CREATE INDEX instance_content_sha1_idx ON instance_content (sha1);

-- Copies of files Atlas changed, taken right before every update or restore.
-- Files live in <app_data_dir>/backups/<instance id>/<backup id>/ with the same relative paths.
CREATE TABLE backup (
  id             TEXT PRIMARY KEY,
  instance_id    TEXT NOT NULL REFERENCES instance (id) ON DELETE CASCADE,
  reason         TEXT NOT NULL CHECK (reason IN ('before_update', 'before_restore', 'before_revert')),
  from_revision  INTEGER,
  to_revision    INTEGER,
  files          TEXT NOT NULL,           -- JSON [{ path, action: 'replaced' | 'removed' | 'added' }] — 'added' files are deleted on restore
  size_bytes     INTEGER NOT NULL,
  created_at     TEXT NOT NULL
);

CREATE INDEX backup_instance_idx ON backup (instance_id, created_at DESC);

-- App settings. value is JSON so one table holds every type.
-- Keys: 'backups_to_keep' (default 3), 'watch_folders', 'atlas_user' (cached profile), 'close_to_tray' ...
CREATE TABLE setting (
  key    TEXT PRIMARY KEY,
  value  TEXT NOT NULL
);

-- Offline cache of cloud responses (friends, shared instances, activity).
-- Deliberately NOT a mirror of the cloud tables: it is safe to wipe at any time.
-- Keys match the API call: 'friends', 'friend_requests', 'shared_instances', 'groups', 'activity', 'shared_instance:<id>'.
CREATE TABLE cloud_cache (
  key         TEXT PRIMARY KEY,
  value       TEXT NOT NULL,             -- JSON, exactly the DTO the frontend receives
  fetched_at  TEXT NOT NULL
);
